@push('scripts')<script>
$(function(){
 const canCreate=@json(auth()->user()->can('cutting.create'));
 const editModalEl=document.getElementById('cuttingModal'), modal=editModalEl?new bootstrap.Modal(editModalEl):null;
 const moModal=new bootstrap.Modal(document.getElementById('cuttingMoModal')), materialModal=new bootstrap.Modal(document.getElementById('cuttingMaterialModal'));
 const table=$('#cuttingTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.cutting.dt')),data:d=>{d.from_date=$('#cuttingFrom').val();d.to_date=$('#cuttingTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-nowrap'},{data:'mo',name:'productionOrder.number'},{data:'user',orderable:false,searchable:false},{data:'number',name:'cutting_number'},{data:'date',name:'processed_at',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''}],order:[[5,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 function safe(value){return $('<div>').text(value??'—').html()}
 function detailMarkup(d){return `<div class="p-3 bg-light-subtle"><div class="table-responsive"><table class="table table-sm table-bordered bg-white mb-0"><thead><tr><th>{{ __('ui.cutting.style') }}</th><th>{{ __('ui.cutting.product_code') }}</th><th>{{ __('ui.cutting.product_name') }}</th><th>{{ __('ui.cutting.unit') }}</th><th>{{ __('ui.cutting.po_buyer') }}</th><th>{{ __('ui.cutting.mo') }}</th><th>{{ __('ui.cutting.quantity') }}</th><th>{{ __('ui.cutting.rejected') }}</th><th>{{ __('ui.cutting.send_to_sewing') }}</th><th>{{ __('ui.cutting.material_code') }}</th><th>{{ __('ui.cutting.material_name') }}</th><th>{{ __('ui.cutting.material_unit') }}</th><th>{{ __('ui.cutting.material_waste') }}</th></tr></thead><tbody><tr><td>${safe(d.style)}</td><td>${safe(d.product_code)}</td><td>${safe(d.product_name)}</td><td>${safe(d.unit)}</td><td>${safe(d.po_buyer)}</td><td>${safe(d.mo)}</td><td class="text-end">${safe(d.input_quantity)}</td><td class="text-end">${safe(d.rejected_quantity)}</td><td class="text-end">${safe(d.good_quantity)}</td><td>${safe(d.material_code)}</td><td>${safe(d.material_name)}</td><td>${safe(d.material_unit)}</td><td class="text-end">${safe(d.material_waste_quantity)}</td></tr></tbody></table></div></div>`}
 $('#cuttingTable').on('click','.btn-show-cutting-detail',function(){const tr=$(this).closest('tr');const row=table.row(tr);if(row.child.isShown()){row.child.hide();tr.removeClass('shown');$(this).text(@json(__('ui.common.detail')))}else{row.child(detailMarkup(row.data())).show();tr.addClass('shown');$(this).text(@json(__('ui.common.close')))}});
 let selectedMo=null; let moTable,materialTable;
 if(canCreate){
  moTable=$('#cuttingMoTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.cutting.production-orders.dt')),columns:[{data:'number',name:'number'},{data:'buyer_po_number',name:'buyer_po_number'},{data:'style',orderable:false,searchable:false},{data:'product_code',orderable:false,searchable:false},{data:'product_name',orderable:false,searchable:false},{data:'unit',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}],drawCallback:()=>window.feather&&feather.replace()});
  materialTable=$('#cuttingMaterialTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.cutting.materials.dt')),data:d=>d.production_order_id=$('#cuttingMoId').val()},columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'unit',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}],drawCallback:()=>window.feather&&feather.replace()});
  const reset=()=>{$('#cuttingForm')[0].reset();$('#cuttingEntryId,#cuttingMoId,#cuttingMaterialId').val('');$('#cuttingDate').val(@json(now()->toDateString()));$('#cuttingNumber').val('');$('#cuttingMoLabel,#cuttingProduct,#cuttingStyle,#cuttingPoBuyer,#cuttingUnit,#cuttingMaterialLabel,#cuttingMaterialUnit').val('');$('#saveCutting').html('<i data-feather="save" class="icon-sm me-1"></i>'+@json(__('ui.common.save')));$.get(@json(route('super.cutting.number-preview'))).done(r=>$('#cuttingNumber').val(r.number));};
  $('#addCutting').on('click',()=>{reset();selectedMo=null;modal.show()});
  $('#chooseCuttingMo').on('click',()=>{modal.hide();moTable.ajax.reload();moModal.show()});
  $(document).on('click','.btn-select-cutting-mo',function(){const b=$(this);selectedMo={id:b.data('id'),number:b.data('number')};$('#cuttingMoId').val(b.data('id'));$('#cuttingMoLabel').val(b.data('number'));$('#cuttingProduct').val(b.data('product'));$('#cuttingStyle').val(b.data('style'));$('#cuttingPoBuyer').val(b.data('po'));$('#cuttingUnit').val(b.data('unit'));moModal.hide();modal.show();materialTable.ajax.reload()});
  $('#chooseCuttingMaterial').on('click',()=>{if(!$('#cuttingMoId').val())return;modal.hide();materialTable.ajax.reload();materialModal.show()});
  $(document).on('click','.btn-select-cutting-material',function(){let b=$(this);$('#cuttingMaterialId').val(b.data('id'));$('#cuttingMaterialLabel').val(b.data('label'));$('#cuttingMaterialUnit').val(b.data('unit'));materialModal.hide();modal.show()});
  $('#cuttingForm').on('submit',function(e){e.preventDefault();let id=$('#cuttingEntryId').val();const url=id?@json(route('super.cutting.update',['entry'=>'__ID__'])).replace('__ID__',id):@json(route('super.cutting.store'));$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',title:@json(__('ui.workflow.success')),text:r.message});}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}));});
  $(document).on('click','.btn-edit-cutting',function(){const b=$(this);reset();$('#cuttingEntryId').val(b.data('id'));$('#cuttingMoId').val(b.data('mo'));$('#cuttingMoLabel').val(b.data('mo-number'));$('#cuttingProduct').val(b.data('product'));$('#cuttingStyle').val(b.data('style'));$('#cuttingPoBuyer').val(b.data('po'));$('#cuttingUnit').val(b.data('unit'));$('#cuttingDate').val(b.data('date'));$('#cuttingQty').val(b.data('input'));$('#cuttingSewing').val(b.data('good'));$('#cuttingReject').val(b.data('reject'));$('#cuttingMaterialId').val(b.data('material'));$('#cuttingMaterialLabel').val(b.data('material-label'));$('#cuttingMaterialUnit').val(b.data('material-unit'));$('#cuttingWaste').val(b.data('waste'));$('#cuttingNumber').val(b.data('number'));$('#saveCutting').text(@json(__('ui.common.save_changes')));modal.show()});
  $(document).on('click','.btn-delete-cutting',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(x=>{if(x.isConfirmed)$.ajax({url:@json(route('super.cutting.destroy',['entry'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(r=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:r.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))})});
 }
 $('#cuttingFilter').on('click',()=>table.ajax.reload());$('#cuttingExport').on('click',function(e){e.preventDefault();let q=new URLSearchParams();if($('#cuttingFrom').val())q.set('from_date',$('#cuttingFrom').val());if($('#cuttingTo').val())q.set('to_date',$('#cuttingTo').val());location.href=this.href+'?'+q.toString()});
});
</script>@endpush
